-- cn_contract_template: 12건
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('EXCLUSIVE', 'EXCLUSIVE', '전속중개', NULL, NULL, '전속중개', 'exclusive', '{"intro": "중개의뢰인(“甲”)과 개업공인중개사(“乙”)는 아래 표시 중개대상물에 대하여 다음과 같이 전속중개계약을 체결한다.", "clauses": ["(개업공인중개사의 의무) 개업공인중개사는 전속중개계약 체결 후 2주에 1회 이상 중개업무 처리상황을 중개의뢰인에게 문서로 통지하고, 중개대상물확인·설명서를 교부한다.", "(중개의뢰인의 의무) 중개의뢰인은 유효기간 내에 스스로 발견한 상대방과 직접 거래하거나 다른 개업공인중개사에게 중복 의뢰한 경우, 약정한 중개보수에 해당하는 금액을 개업공인중개사에게 지급한다.", "(유효기간) 본 계약의 유효기간은 위 유효기간으로 하며, 당사자 간 별도 약정이 없으면 3개월로 한다.", "(중개보수) 중개대상물의 거래가 성사된 때에 중개의뢰인은 위 중개보수를 개업공인중개사에게 지급한다.", "(비용부담) 개업공인중개사는 통상의 중개업무에 소요되는 비용을 부담하되, 중개의뢰인의 특별한 요청에 의한 비용은 중개의뢰인이 부담한다."], "docHint": "전속중개", "parties": [{"role": "중개의뢰인", "label": "중개의뢰인"}], "objective": "제1조 (목적) 중개의뢰인은 위 중개대상물의 중개를 개업공인중개사에게 전속으로 의뢰하고, 개업공인중개사는 이를 승낙한다.", "amountRows": [{"text": ["金 ", {"k": "거래예정가격한글", "w": "45%", "ph": "금액(한글)"}, " 원정 (₩ ", {"k": "거래예정가격", "w": "30%", "ph": "숫자"}, " )"], "label": "거래예정가격"}, {"text": [{"k": "전속시작", "w": "120px", "ph": "년 월 일"}, " 부터 ", {"k": "전속종료", "w": "120px", "ph": "년 월 일"}, " 까지"], "label": "유효기간"}, {"text": ["거래가액의 ", {"k": "중개보수요율", "w": "60px"}, " % (또는 金 ", {"k": "중개보수한글", "w": "30%"}, " 원정)"], "label": "중개보수"}], "propertyTitle": "중개대상물의 표시"}', 2, 12, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('OCCUP_SALE', 'OCCUP', '입주권', 'SALE', '매매', '입주권 매매', 'ipjugwon', '{"intro": "매도인과 매수인 쌍방은 아래 표시 부동산에 관하여 다음 계약내용과 같이 매매계약을 체결한다.", "clauses": [["매도인은 잔금 수령과 동시에 매수인에게 조합원 지위 승계 및 소유권 이전 등기에 관한 서류 일체를 교부하고 이주비, 이사비 및 조합원 지위 승계 및 등기절차에 협력하며, 위 부동산 인도일은 ", {"k": "인도일자", "w": "150px", "ph": "년      월      일"}, " 로 한다."], "잔금일 기준으로 조합원의 지위 및 권리와 의무가 자동승계 된다. 또한 잔금일 이전 확정 및 부과고지 된 추가부담금 내역은 매도자가, 잔금일 이후 조합정관, 조합총회 및 의결에 따라 발생하는 추가부담금은 매수자가 납부한다.", "잔금지급일 기준 매도자의 귀책사유로 조합원 지위가 승계되지 않는 경우 본 계약은 무효로 하고, 매수자가 지급한 취득세 및 지급한 금액은 전액 반환하기로 한다.", "매도인은 위 부동산에 설정된 저당권, 지상권, 임차권 등 소유권의 행사를 제한하는 사유가 있거나, 제세공과 기타 부담금의 미납금 등이 있을 때에는 잔금 수수일까지 그 권리의 하자 및 부담 등을 제거하여 완전한 소유권을 매수인에게 이전한다. 다만 승계하기로 합의하는 권리 및 금액은 그러하지 아니한다.", "위 부동산에 관하여 발생한 수익의 귀속과 제세공과금, 지연이자 등의 부담은 위 부동산의 인도일을 기준으로 하되, 지방세의 납부의무 및 납부책임은 지방세법에 따른다.", "매수인이 매도인에게 중도금(중도금이 없을때에는 잔금)을 지불하기 전 까지 매도인은 계약금의 배액을 상환하고, 매수인은 계약금을 포기하고 본 계약을 해제할 수 있다.", "매도인 또는 매수인이 본 계약상의 내용을 불이행한 경우 그 상대방은 불이행한 자에 대하여 계약의 해제 및 손해배상을 청구할 수 있으며, 해제에 따른 손해배상은 별도의 약정이 없는 한 계약금을 기준으로 한다.", "중개보수는 본 계약 체결에 따라 당사자 쌍방이 각각 지급하며, 개업공인중개사의 고의나 과실 없이 거래당사자의 사정으로 본 계약이 해약되어도 중개보수는 지급한다.", "매도인 또는 매수인이 본 계약 이외의 업무를 의뢰한 경우 이에 관한 보수는 중개보수와는 별도로 지급하여야 하며 그 금액은 합의에 의한다.", "개업공인중개사는 중개대상물 확인설명서 및 정비사업구역 안 설명고지 확인서를 작성하고 업무보증관계증서(공제증서 등) 사본을 첨부하여 거래당사자 쌍방에게 교부한다."], "docHint": "입주권", "parties": [{"role": "매도인", "label": "매도인"}, {"role": "매수인", "label": "매수인"}], "objective": "", "amountRows": [], "propertyTitle": "부동산 표시"}', 1, 8, 'Y', '2026-09-11 20:08:40', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('PREMIUM', 'PREMIUM', '권리금', NULL, NULL, '권리금', 'keymoney', '{"intro": "", "clauses": ["[임차인의 의무] ① 임차인은 신규임차인을 임대인에게 주선하여야 하며, 임대인과 신규임차인 간에 임대차계약이 체결될 수 있도록 협력하여야 한다. ② 임차인은 신규임차인이 정상적인 영업을 개시할 수 있도록 전화가입권의 이전, 사업등록의 폐지 등에 협력하여야 한다. ③ 임차인은 신규임차인이 잔금을 지급할 때까지 권리금의 대가로 위 유형·무형의 재산적 가치를 이전한다. ④ 임차인은 신규임차인에게 재산적 가치를 이전할 때까지 선량한 관리자로서의 주의의무를 다하여 유지·관리하여야 한다. ⑤ 임차인은 본 계약체결 후 신규임차인이 잔금을 지급할 때까지 임차목적물상 권리관계, 보증금, 월차임 등 임대차계약 내용이 변경된 경우 또는 영업정지 및 취소, 철거명령 등 영업을 지속할 수 없는 사유가 발생한 경우 이를 즉시 신규임차인에게 고지하여야 한다.", "[임대차계약과의 관계] 임대인의 계약거절, 무리한 임대조건 변경, 목적물의 훼손 등 임차인과 신규임차인의 책임 없는 사유로 임대차계약이 체결되지 못하는 경우 본 계약은 무효로 하며, 임차인은 지급받은 계약금 등을 신규임차인에게 즉시 반환하여야 한다.", "[계약의 해제 및 손해배상] ① 신규임차인이 중도금(중도금 약정이 없을 때는 잔금)을 지급하기 전까지 임차인은 계약금의 2배를 배상하고, 신규임차인은 계약금을 포기하고 본 계약을 해제할 수 있다. ② 임차인 또는 신규임차인이 본 계약상의 내용을 이행하지 않는 경우 그 상대방은 서면으로 최고하고 계약을 해제할 수 있다. ③ 본 계약체결 이후 임차인의 영업기간 중 발생한 사유로 인한 영업정지 및 취소, 철거명령 등으로 신규임차인이 영업을 개시하지 못하거나 지속할 수 없는 중대한 하자가 발생한 경우 신규임차인은 계약을 해제하거나 손해배상을 청구할 수 있다. ④ 계약의 해제 및 손해배상에 관하여 이 계약서에 정함이 없는 경우 「민법」의 규정에 따른다."], "docHint": "권리금", "parties": [{"role": "임차인", "label": "임차인"}, {"role": "신규임차인", "label": "신규임차인"}], "objective": "", "amountRows": [], "propertyTitle": "임대차목적물인 상가건물의 표시"}', 1, 10, 'Y', '2026-09-11 20:08:40', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('PRESALE_SALE', 'PRESALE', '분양권', 'SALE', '매매', '분양권 매매', 'bunyang', '{"intro": "매도인과 매수인 쌍방은 아래 표시 부동산에 관하여 다음 계약내용과 같이 매매계약을 체결한다.", "clauses": ["잔금 지불과 동시에 매매물건(분양계약서 당첨권 등)을 교부하고, 인감증명서 등 서류제출이 필요시에는 변경된 경우에도 즉시 제출해주기로 한다.", "본 계약을 매도자가 위반한 경우, 계약금액의 배액을 배상해 주어야 하며, 매수자가 본 계약을 위반한 경우, 계약금은 매도자에게 귀속된다.", "본 계약서에 기재되지 않은 사항은 관련법과 일반관례에 따른다. 또한, 지정 기일 중 중도금을 납부하지 않음으로써 발생한 이자 등은 잔금일을 기준으로 계산한다.", "중개보수는 본 계약의 체결에 따라 당사자 쌍방이 각각 지불하며, 개업공인중개사의 고의나 과실 없이 거래당사자 사정으로 본 계약이 해약되어도 중개보수는 지급한다.", "본 계약은 쌍방 합의에 의하여 계약을 체결하는 것으로 매도자에게 지불할 금액은 위와 같으며 쌍방 확인 후 기명 날인한다.", "[중개대상물 확인설명서 교부 등] 개업공인중개사는 중개대상물 확인설명서를 작성하고 업무보증관계증서(공제증서 등) 사본을 첨부하여 거래당사자 쌍방에게 교부한다."], "docHint": "분양권", "parties": [{"role": "매도인", "label": "매도인"}, {"role": "매수인", "label": "매수인"}], "objective": "", "amountRows": [], "propertyTitle": "부동산 표시"}', 2, 7, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('REAL_ASSIGN', 'REAL', '부동산', 'ASSIGN', '권리양도', '부동산 권리양도', 'assign', '{"intro": "본 부동산에 대하여 양도인과 양수인은 합의에 의하여 다음과 같이 부동산 권리 양도계약을 체결한다.", "clauses": [["(인도 및 기간) 양도인은 위 부동산의 권리 행사를 할 수 있는 상태로 하여 ", {"k": "인도일자", "w": "150px", "ph": "년      월      일"}, " 까지 양수인에게 인도하며, 임대차기간은 인도일로부터 ", {"k": "임대차종료", "w": "150px", "ph": "년      월      일"}, " 까지 ( ", {"k": "임대차개월", "w": "46px"}, " ) 개월로 한다."], "(시설 인계) 양도인은 임차권의 행사를 방해하는 제반 사항을 제거하고, 잔금수령과 동시에 양수인이 즉시 영업 할 수 있도록 모든 시설을 포함 인계하여 주어야 한다. 다만, 약정을 달리한 경우에는 그러하지 아니한다.", "(제세공과금) 위 부동산에 관하여 발생한 수익의 귀속과 조세공과금 등의 부담은 위 부동산의 인도일을 기준으로 하여 그 이전까지는 양도인에게 그 이후의 것은 양수인에게 각각 귀속한다. 단 지방세의 납부의무 및 납부책임은 지방세법의 규정에 따른다.", "(계약의 해제) 양수인이 중도금(중도금약정이 없을 때는 잔금)을 지불하기 전까지 양도인은 계약금의 배액을 배상하고, 양수인은 계약금을 포기하고 본 계약을 해제할 수 있다.", "(중개보수) 공인중개사는 계약 당사자간의 채무불이행에 대해서는 책임지지 않는다. 또한 중개수수료는 본 계약의 체결과 동시에 본 계약이 해제되어도 중개수수료를 지급한다.", "(임대차계약 체결 협력) 양도인은 잔금지급일 이전까지 소유자(임대인)와 양수인 간에 임대차계약이 체결되도록 협력한다.", "(중개대상물 확인·설명서 교부 등) 「공인중개사의 업무 및 부동산 거래신고에 관한 법」 제25조3항의 규정에 의거 중개대상물 확인설명서를 작성하여 거래당사자 쌍방에게 교부한다."], "docHint": "권리양도", "parties": [{"role": "양도인", "label": "양도인"}, {"role": "양수인", "label": "양수인"}], "objective": "제1조 위 부동산의 권리금액을 아래와 같이 지불하기로 한다.", "amountRows": [{"text": ["金 ", {"k": "권리양도금한글", "w": "48%"}, " 원정 (₩ ", {"k": "권리양도금", "w": "28%"}, " )"], "label": "권리금액"}, {"text": ["金 ", {"k": "계약금한글", "w": "48%"}, " 원정은 계약시 지불하고 영수함."], "label": "계약금"}, {"text": ["金 ", {"k": "중도금1한글", "w": "38%"}, " 원정은 ", {"k": "중도금1일자", "w": "150px", "ph": "년      월      일"}, " 에 지불하며,"], "label": "중도금"}, {"text": ["金 ", {"k": "중도금2한글", "w": "38%"}, " 원정은 ", {"k": "중도금2일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "중도금"}, {"text": ["金 ", {"k": "잔금한글", "w": "38%"}, " 원정은 ", {"k": "잔금일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "잔금"}], "propertyTitle": "부동산의 표시"}', 2, 5, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('REAL_EXCHANGE', 'REAL', '부동산', 'EXCHANGE', '교환', '부동산 교환', 'exchange', '{"intro": "“甲”과 “乙”은 다음과 같이 상호 합의하에 부동산 교환계약을 체결한다.", "clauses": ["(소유권 이전 등) “甲”과 “乙”은 교환 차액의 잔금수령과 동시에 소유권 이전등기와 기타 권리이전에 대한 제반 서류를 상대방에게 넘겨주어야 하며, 교환차액이 발생하지 않을 시에는 물건교환 일에 제반서류를 교환하기로 한다.", "(제세공과금) 각종 세금 및 제반공과금 등은 잔액 지불 일을 기준으로 “甲”의 물건에 대하여는 “甲”이 “乙”의 물건에 대하여는 “乙”이 부담하기로 한다.", "(계약의 해제) 거래 당사자 일방은 중도금(중도금약정이 없을 때는 잔금)을 지불하기 전까지 상대방에게 계약금액의 배액을 배상하고, 본인은 계약금을 포기하고 본 계약을 해제할 수 있다.", "(채무불이행과 손해배상) “甲”과 “乙”은 본 계약상의 채무불이행이 있을 경우 계약당사자 일방은 채무불이행한 상대방에 대하여 서면으로 이행을 최고하고, 이를 이행하지 않을 경우 계약을 해제 할 수 있다. 이 경우 “甲”과 “乙”은 각각 상대방에 대하여 손해배상을 청구할 수 있으며, 손해배상에 대하여 별도 약정이 없는 한 제4조의 기준을 따른다.", "(중개보수) 공인중개사는 계약 당사자간의 채무불이행에 대해서는 책임지지 않는다. 또한 중개수수료는 본 계약의 체결과 동시에 계약당사자간의 사정으로 본 계약이 해제되어도 중개수수료를 지급한다.", "(중개대상물 확인·설명서 교부 등) 「공인중개사의 업무 및 부동산 거래신고에 관한 법」 제25조3항의 규정에 의거 중개대상물 확인설명서를 작성하여 거래당사자 쌍방에게 교부한다."], "docHint": "교환", "parties": [{"role": "갑", "label": "甲(교환자)"}, {"role": "을", "label": "乙(교환자)"}], "objective": "제1조 위 부동산의 교환 계약을 체결함에 있어 계약당사자간의 합의하에 교환 차액을 아래와 같이 지불하기로 한다.", "amountRows": [{"text": ["金 ", {"k": "교환차액한글", "w": "48%"}, " 원정 (₩ ", {"k": "교환차액", "w": "28%"}, " )"], "label": "교환차액"}, {"text": ["金 ", {"k": "계약금한글", "w": "48%"}, " 원정은 계약시 지불하고 영수함."], "label": "계약금"}, {"text": ["金 ", {"k": "중도금1한글", "w": "38%"}, " 원정은 ", {"k": "중도금1일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "중도금"}, {"text": ["金 ", {"k": "잔금한글", "w": "38%"}, " 원정은 ", {"k": "잔금일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "잔금"}], "propertyTitle": "부동산의 표시"}', 2, 4, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('REAL_JEONSE', 'REAL', '부동산', 'JEONSE', '전세', '부동산 전세', 'jeonse', '{"intro": "임대인과 임차인 쌍방은 아래 표시 부동산에 관하여 다음 내용과 같이 임대차계약을 체결한다.", "clauses": [["(존속기간) 임대인은 위 부동산을 임대차 목적대로 사용할 수 있는 상태로 하여 ", {"k": "인도일자", "w": "150px", "ph": "년      월      일"}, " 까지 임차인에게 인도하며, 임대차기간은 인도일로부터 ", {"k": "임대차개월", "w": "46px"}, " 개월인 ", {"k": "임대차종료", "w": "150px", "ph": "년      월      일"}, " 까지로 한다."], "(용도변경 및 전대 등) 임차인은 임대인의 동의 없이 위 부동산의 용도나 구조를 변경하거나 전대, 임차권 양도 또는 담보제공을 하지 못하며 임대차 목적 이외의 용도로 사용할 수 없다.", "(계약의 해지) 임차인이 제3조를 위반하였을 때 임대인은 즉시 본 계약을 해지할 수 있다.", "(계약의 종료) 임대차계약이 종료된 경우에 임차인은 위 부동산을 원상으로 회복하여 임대인에게 반환한다. 이러한 경우 임대인은 보증금을 임차인에게 반환하고, 연체 임대료 또는 손해배상금이 있을 때는 이들을 제하고 그 잔액을 반환한다.", "(계약의 해제) 임차인이 임대인에게 중도금(중도금이 없을 때는 잔금)을 지불하기 전까지, 임대인은 계약금의 배액을 상환하고, 임차인은 계약금을 포기하고 이 계약을 해제할 수 있다.", "(채무불이행과 손해배상) 임대인 또는 임차인이 본 계약상의 내용에 대하여 불이행이 있을 경우 그 상대방은 불이행한 자에 대하여 서면으로 최고하고 계약을 해제할 수 있다. 그리고 계약 당사자는 계약해제에 따른 손해배상을 각각 상대방에 대하여 청구할 수 있으며, 손해배상에 대하여 별도의 약정이 없는 한 계약금을 손해배상의 기준으로 본다.", "(중개보수) 개업공인중개사는 계약 당사자의 본 계약 불이행에 대하여 책임지지 않으며, 개업공인중개사의 고의나 과실없이 본 계약이 무효, 취소, 해제 되어도 중개보수는 지급한다. 중개보수는 본 계약 체결시에 계약 당사자 쌍방이 각각 지불하되, 확인설명서에 별도의 지급일이 있으면 그에 따른다. 공동중개인 경우 계약 당사자는 자신이 중개의뢰한 개업공인중개사에게 각각 중개보수를 지급한다.", "(중개대상물확인·설명서 교부등) 개업공인중개사는 중개대상물 확인·설명서를 작성하고 업무보증관계증서(공제증서 등) 사본을 첨부하여 거래당사자 쌍방에게 교부한다."], "docHint": "전세", "parties": [{"role": "임대인", "label": "임대인"}, {"role": "임차인", "label": "임차인"}], "objective": "제1조 위 부동산의 임대차에 한하여 임차인은 임차보증금을 아래와 같이 지불하기로 한다.", "amountRows": [{"text": ["金 ", {"k": "보증금한글", "w": "48%"}, " 원정 (₩ ", {"k": "보증금", "w": "28%", "ph": "숫자"}, " )"], "label": "보증금"}, {"text": ["金 ", {"k": "계약금한글", "w": "48%"}, " 원정은 계약시에 지불하고 영수함."], "label": "계약금"}, {"text": ["金 ", {"k": "중도금1한글", "w": "38%"}, " 원정은 ", {"k": "중도금1일자", "w": "150px", "ph": "년      월      일"}, " 에 지불하며"], "label": "중도금"}, {"text": ["金 ", {"k": "중도금2한글", "w": "38%"}, " 원정은 ", {"k": "중도금2일자", "w": "150px", "ph": "년      월      일"}, " 에 지불하며"], "label": "중도금"}, {"text": ["金 ", {"k": "잔금한글", "w": "38%"}, " 원정은 ", {"k": "잔금일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "잔금"}], "propertyTitle": "부동산의 표시"}', 2, 2, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('REAL_LANDAGREE', 'REAL', '부동산', 'SALE', '매매약정', '부동산 매매약정', 'landAgree', '{"intro": "「부동산 거래신고 등에 관한 법률」 제11조제1항에 의하여 토지거래허가구역 등에서 토지거래허가를 득하고 매매계약을 하기 위해 상호 합의하고 아래의 내용을 약정한다.", "clauses": ["(토지거래허가 신청) 약정 당사자 쌍방이 협력하여 토지거래허가신청을 한다.", "(불이행·위반) 쌍방 어느 한쪽이 협조하지 않아 토지거래허가를 득하지 못할 경우, 협조하지 않은 측은 손해배상으로 금 원을 상대방에게 변상해야 한다. 즉, 부동산 소유자가 협조하지 않은 경우 약정금의 배액을 상환해야 하며, 매수약정인이 협조하지 않은 경우 지급한 약정금은 포기한다. 또한, 약정한 내용을 위반한 때에는 위반한 측에서 금 원을 지급하기로 하며 매매약정을 취소한 경우에는 취소를 원하는 측에서 금 원을 지급해야 한다. 다만, 쌍방이 적극 협력했음에도 불구하고 토지거래허가를 득하지 못한 경우에 본 약정은 무효로 하며 약정 관련 모든 서류는 즉시 파기한다.", "(매매계약 체결) 토지거래허가를 득한 후 매매계약은 일주일 이내 체결해야 하며, 다른 약정이 없는 한 부동산 소유자는 약정금의 배액을 상환하고, 매수약정인은 약정금을 포기하고 약정을 해제할 수 있고, 약정 후 부동산 소유자·매수약정인 어느 한 쪽이 매매계약을 불이행하는 경우는 약정금을 위약금으로 본다.", "(기타) 본 약정서에 기재되지 않은 사항은 관련 법률 규정에 의한다.", "(중개보수) 중개보수는 토지거래허가를 득한 후 매매 계약 시에 약정당사자 쌍방이 각각 지불한다."], "docHint": "매매약정", "parties": [{"role": "매도인", "label": "매도인"}, {"role": "매수인", "label": "매수인"}], "hasAgent": true, "objective": "제1조 (약정내용) 위 부동산 소유자와 매수약정인은 쌍방 협의 하에 아래와 같이 매매약정을 체결하며, 위 부동산의 매매예정금액과 매매약정금을 아래와 같이 정한다.", "amountRows": [{"text": ["金 ", {"k": "매매대금한글", "w": "48%"}, " 원정 (₩ ", {"k": "매매대금", "w": "28%", "ph": "숫자"}, " )"], "label": "매매예정금액"}, {"text": ["金 ", {"k": "계약금한글", "w": "48%"}, " 원정 (₩ ", {"k": "계약금", "w": "28%", "ph": "숫자"}, " )"], "label": "매매약정금"}], "propertyTitle": "약정한 부동산의 표시", "propertyHeading": "제1조 약정한 부동산의 표시"}', 1, 6, 'Y', '2026-09-11 20:08:40', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('REAL_SALE', 'REAL', '부동산', 'SALE', '매매', '부동산 매매', 'sale', '{"intro": "매도인과 매수인 쌍방은 아래 표시 부동산에 관하여 다음 내용과 같이 매매계약을 체결한다.", "clauses": [["(소유권 이전 등) 매도인은 매매대금의 잔금 수령과 동시에 매수인에게 소유권이전등기에 필요한 모든 서류를 교부하고 등기절차에 협력하며, 위 부동산의 인도일은 ", {"k": "인도일자", "w": "150px", "ph": "년      월      일"}, " 로 한다."], "(제한물권 등의 소멸) 매도인은 위 부동산에 설정된 저당권, 지상권, 임차권 등 소유권의 행사를 제한하는 사유가 있거나, 제세공과 기타 부담금의 미납금 등이 있을 때에는 잔금일까지 그 권리의 하자 및 부담 등을 제거하여 완전한 소유권을 매수인에게 이전한다. 다만, 승계하기로 합의하는 권리 및 금액은 그러하지 아니하다.", "(지방세 등) 위 부동산에 관하여 발생한 수익의 귀속과 제세공과금 등의 부담은 위 부동산의 인도일을 기준으로 하되, 지방세의 납부의무 및 납부책임은 지방세법의 규정에 의한다.", "(계약의 해제) 매수인이 매도인에게 중도금(중도금이 없을때에는 잔금)을 지불하기 전까지 매도인은 계약금의 배액을 상환하고, 매수인은 계약금을 포기하고 본 계약을 해제할 수 있다.", "(채무불이행과 손해배상) 매도인 또는 매수인이 본 계약상의 내용에 대하여 불이행이 있을 경우 그 상대방은 불이행한자에 대하여 서면으로 최고하고 계약을 해제할 수 있다. 그리고 계약당사자는 계약해제에 따른 손해배상을 각각 상대방에게 청구할 수 있으며, 손해배상에 대하여 별도의 약정이 없는 한 계약금을 손해배상의 기준으로 본다.", "(중개보수) 개업공인중개사는 매도인 또는 매수인의 본 계약 불이행에 대하여 책임을 지지 않는다. 또한 중개보수는 본 계약체결과 동시에 계약 당사자 쌍방이 각각 지불하며, 개업공인중개사의 고의나 과실없이 본 계약이 무효, 취소 또는 해제되어도 중개보수는 지급한다. 공동 중개인 경우 매도인과 매수인은 자신이 중개 의뢰한 개업공인중개사에게 각각 중개보수를 지급한다.", "(중개보수 외) 매도인 또는 매수인이 본 계약 이외의 업무를 의뢰한 경우 이에 관한 보수는 중개보수와는 별도로 지급하며 그 금액은 합의에 의한다.", "(중개대상물확인·설명서 교부 등) 개업공인중개사는 중개대상물 확인·설명서를 작성하고 업무보증관계증서(공제증서 등) 사본을 첨부하여 계약체결과 동시에 거래당사자 쌍방에게 교부한다."], "docHint": "매매", "parties": [{"role": "매도인", "label": "매도인"}, {"role": "매수인", "label": "매수인"}], "hasAgent": true, "objective": "제1조 위 부동산의 매매에 있어 매도인과 매수인은 합의에 의하여 매매대금을 아래와 같이 지불하기로 한다.", "amountRows": [{"text": ["金 ", {"k": "매매대금한글", "w": "48%"}, " 원정 (₩ ", {"k": "매매대금", "w": "28%", "ph": "숫자"}, " )"], "label": "매매대금"}, {"text": ["金 ", {"k": "융자금한글", "w": "48%"}, " 원정은 현상태에서 승계함."], "label": "융자금"}, {"text": ["金 ", {"k": "계약금한글", "w": "48%"}, " 원정은 계약시에 지불하고 영수함."], "label": "계약금"}, {"text": ["金 ", {"k": "중도금1한글", "w": "38%"}, " 원정은 ", {"k": "중도금1일자", "w": "150px", "ph": "년      월      일"}, " 에 지불하며"], "label": "중도금"}, {"text": ["金 ", {"k": "중도금2한글", "w": "38%"}, " 원정은 ", {"k": "중도금2일자", "w": "150px", "ph": "년      월      일"}, " 에 지불하며"], "label": "중도금"}, {"text": ["金 ", {"k": "잔금한글", "w": "38%"}, " 원정은 ", {"k": "잔금일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "잔금"}], "propertyTitle": "부동산의 표시"}', 2, 1, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('REAL_WOLSE', 'REAL', '부동산', 'WOLSE', '월세', '부동산 월세', 'wolse', '{"intro": "임대인과 임차인 쌍방은 아래 표시 부동산에 관하여 다음 내용과 같이 임대차계약을 체결한다.", "clauses": [["(존속기간) 임대인은 위 부동산을 임대차 목적대로 사용할 수 있는 상태로 하여 ", {"k": "인도일자", "w": "150px", "ph": "년      월      일"}, " 까지 임차인에게 인도하며, 임대차기간은 인도일로부터 ", {"k": "임대차개월", "w": "46px"}, " 개월인 ", {"k": "임대차종료", "w": "150px", "ph": "년      월      일"}, " 까지로 한다."], "(용도변경 및 전대 등) 임차인은 임대인의 동의 없이 위 부동산의 용도나 구조를 변경하거나 전대, 임차권 양도 또는 담보제공을 하지 못하며 임대차 목적 이외의 용도로 사용할 수 없다.", "(계약의 해지) 임차인이 제3조를 위반하였을 때 임대인은 즉시 본 계약을 해지할 수 있다.", "(계약의 종료) 임대차계약이 종료된 경우에 임차인은 위 부동산을 원상으로 회복하여 임대인에게 반환한다. 이러한 경우 임대인은 보증금을 임차인에게 반환하고, 연체 임대료 또는 손해배상금이 있을 때는 이들을 제하고 그 잔액을 반환한다.", "(계약의 해제) 임차인이 임대인에게 중도금(중도금이 없을 때는 잔금)을 지불하기 전까지, 임대인은 계약금의 배액을 상환하고, 임차인은 계약금을 포기하고 이 계약을 해제할 수 있다.", "(채무불이행과 손해배상) 임대인 또는 임차인이 본 계약상의 내용에 대하여 불이행이 있을 경우 그 상대방은 불이행한 자에 대하여 서면으로 최고하고 계약을 해제할 수 있다. 그리고 계약 당사자는 계약해제에 따른 손해배상을 각각 상대방에 대하여 청구할 수 있으며, 손해배상에 대하여 별도의 약정이 없는 한 계약금을 손해배상의 기준으로 본다.", "(중개보수) 개업공인중개사는 계약 당사자의 본 계약 불이행에 대하여 책임지지 않으며, 개업공인중개사의 고의나 과실없이 본 계약이 무효, 취소, 해제 되어도 중개보수는 지급한다. 중개보수는 본 계약 체결시에 계약 당사자 쌍방이 각각 지불하되, 확인설명서에 별도의 지급일이 있으면 그에 따른다. 공동중개인 경우 계약 당사자는 자신이 중개의뢰한 개업공인중개사에게 각각 중개보수를 지급한다.", "(중개대상물확인·설명서 교부등) 개업공인중개사는 중개대상물 확인·설명서를 작성하고 업무보증관계증서(공제증서 등) 사본을 첨부하여 거래당사자 쌍방에게 교부한다."], "docHint": "월세", "parties": [{"role": "임대인", "label": "임대인"}, {"role": "임차인", "label": "임차인"}], "objective": "제1조 (목적) 위 부동산의 임대차에 한하여 임대인과 임차인은 합의에 의하여 임차보증금 및 차임을 아래와 같이 지불하기로 한다.", "amountRows": [{"text": ["金 ", {"k": "보증금한글", "w": "48%"}, " 원정 (₩ ", {"k": "보증금", "w": "28%", "ph": "숫자"}, " )"], "label": "보증금"}, {"text": ["金 ", {"k": "계약금한글", "w": "48%"}, " 원정은 계약시에 지불하고 영수함."], "label": "계약금"}, {"text": ["金 ", {"k": "중도금1한글", "w": "38%"}, " 원정은 ", {"k": "중도금1일자", "w": "150px", "ph": "년      월      일"}, " 에 지불하며"], "label": "중도금"}, {"text": ["金 ", {"k": "중도금2한글", "w": "38%"}, " 원정은 ", {"k": "중도금2일자", "w": "150px", "ph": "년      월      일"}, " 에 지불하며"], "label": "중도금"}, {"text": ["金 ", {"k": "잔금한글", "w": "38%"}, " 원정은 ", {"k": "잔금일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "잔금"}, {"text": ["金 ", {"k": "월세한글", "w": "38%"}, " 원정은 매월 ", {"k": "월세지급일", "w": "46px"}, " 일에 지불한다."], "label": "차임(월세)"}], "propertyTitle": "부동산의 표시"}', 2, 3, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
