INSERT OR IGNORE INTO "cn_contract_template" ("tpl_code", "kind_cd", "kind_nm", "trade_cd", "trade_nm", "label", "category", "body_json", "ver", "sort", "use_yn", "reg_dt", "reg_id", "upd_dt", "upd_id") VALUES ('SUBLEASE', 'SUBLEASE', '전대차', 'WOLSE', '전대차', '전대차', 'sublease', '{"intro": "본 부동산에 대하여 전대인과 전차인 쌍방은 합의에 의하여 다음과 같이 전대차계약을 체결한다.", "clauses": [["(존속기간) 전대인은 위 부동산을 전대차 목적으로 사용 수익할 수 있는 상태로 하여 ", {"k": "인도일자", "w": "150px", "ph": "년      월      일"}, " 까지 전차인에게 인도하며, 전대차기간은 인도일로부터 ", {"k": "임대차종료", "w": "150px", "ph": "년      월      일"}, " 까지 ( ", {"k": "임대차개월", "w": "46px"}, " )개월로 한다."], "(용도변경 및 전대 등) 전차인은 전대인의 동의 없이 위 부동산의 용도나 구조를 변경하거나 전대 또는 담보제공을 하지 못하며 전대차목적 이외 용도에 사용할 수 없다.", "(계약의 해지) 전차인이 2회 이상 차임 지급을 연체하거나, 제3조를 위반하였을 경우 전대인은 본 계약을 해지할 수 있다.", "(계약의 종료) 전대차계약이 종료한 경우 전차인은 위 부동산을 원상으로 회복하여 전대인에게 반환하며, 전대인은 보증금을 전차인에게 반환한다.", "(계약의 해제) 전차인이 전대인에게 중도금(중도금이 없을 때는 잔금)을 지불하기 전까지는 전대인은 계약금의 배액을 상환하고, 전차인은 계약금을 포기하고 본 계약을 해제할 수 있다.", "(중개보수) 공인중개사는 계약 당사자간의 채무불이행에 대해서는 책임지지 않는다. 또한 중개수수료는 본 계약의 체결과 동시에 본 계약이 해제되어도 중개수수료를 지급한다.", "(중개대상물 확인·설명서 교부 등) 「공인중개사의 업무 및 부동산 거래신고에 관한 법」 제25조3항의 규정에 의거 중개대상물 확인설명서와 공제증서 사본을 거래당사자 쌍방에게 교부한다."], "docHint": "전대차", "parties": [{"role": "전대인", "label": "전대인"}, {"role": "전차인", "label": "전차인"}], "objective": "제1조 위 부동산의 전대차계약에 있어 전차인은 보증금 및 차임을 아래와 같이 지불하기로 한다.", "amountRows": [{"text": ["金 ", {"k": "보증금한글", "w": "48%"}, " 원정 (₩ ", {"k": "보증금", "w": "28%"}, " )"], "label": "보증금"}, {"text": ["金 ", {"k": "계약금한글", "w": "48%"}, " 원정은 계약시 지불하고 영수함."], "label": "계약금"}, {"text": ["金 ", {"k": "중도금1한글", "w": "38%"}, " 원정은 ", {"k": "중도금1일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "중도금"}, {"text": ["金 ", {"k": "잔금한글", "w": "38%"}, " 원정은 ", {"k": "잔금일자", "w": "150px", "ph": "년      월      일"}, " 에 지불한다."], "label": "잔금"}, {"text": ["金 ", {"k": "월세한글", "w": "38%"}, " 원정은 매월 ", {"k": "월세지급일", "w": "46px"}, " 일에 지불한다."], "label": "차임"}], "propertyTitle": "부동산의 표시"}', 2, 9, 'Y', '2026-09-11 19:23:25', 'admin', '2026-09-11 20:08:40', 'admin');
